import { createApp } from './src/app.ts';

const app = createApp();

async function get(path: string) {
	const res = await app.handle(new Request(`http://localhost${path}`));
	return { status: res.status, body: await res.text() };
}

const json = await get('/api/v1/docs/json');
console.log('docs/json status:', json.status);
const spec = JSON.parse(json.body);
console.log('openapi:', spec.openapi);
console.log('info:', JSON.stringify(spec.info));
const paths = Object.keys(spec.paths).sort();
console.log('paths:');
for (const p of paths) {
	console.log('  ', p, '->', Object.keys(spec.paths[p]).join(','));
}
// Check TypeBox constraint reflected: createHabit name minLength
const post = spec.paths['/api/v1/habits']?.post;
const bodyRef = post?.requestBody?.content?.['application/json']?.schema;
console.log('POST /habits body schema:', JSON.stringify(bodyRef));
// checkin date pattern
const cin = spec.paths['/api/v1/habits/{id}/checkins']?.post?.requestBody?.content?.['application/json']?.schema;
console.log('POST checkins body schema:', JSON.stringify(cin));
EOF
